        MEDIUM,
        HIGH,
        CRITICAL
    }

    public static final class SecurityEvent {
        public final EventType type;
        public final Severity severity;
        public final String user;
        public final String sourceIp;
        public final String message;
        public final long timestamp;

        public SecurityEvent(EventType type, Severity severity, String user, String sourceIp, String message, long timestamp) {
            this.type = type;
            this.severity = severity;
            this.user = user;
            this.sourceIp = sourceIp;
            this.message = message;
            this.timestamp = timestamp;
        }
    }

    public static final class SecurityEventStore {
        public final List<SecurityEvent> events = new ArrayList<SecurityEvent>();
    }

    public static final class MonitorResult {
        public final boolean alert;
        public final int count;
        public final List<SecurityEvent> matchingEvents;
        public final Severity minimumSeverity;
        public final int threshold;

        public MonitorResult(boolean alert, int count, List<SecurityEvent> matchingEvents, Severity minimumSeverity, int threshold) {
            this.alert = alert;
            this.count = count;
            this.matchingEvents = matchingEvents;
            this.minimumSeverity = minimumSeverity;
            this.threshold = threshold;
        }
    }

    public static SecurityEvent createEvent(EventType type, Severity severity, String user, String sourceIp, String message, long timestamp) {
        return new SecurityEvent(type, severity, user, sourceIp, message, timestamp);
    }

    public static boolean logEvent(SecurityEventStore store, SecurityEvent event) {
        if (store == null || event == null) {
            return false;
        }
        return store.events.add(event);
    }

    public static MonitorResult monitorEvents(SecurityEventStore store, Severity minimumSeverity, int threshold, long timeWindowMillis, long currentTime) {
        List<SecurityEvent> matching = new ArrayList<SecurityEvent>();

        if (store != null && minimumSeverity != null && threshold > 0 && timeWindowMillis >= 0) {
            long windowStart = currentTime - timeWindowMillis;

            for (SecurityEvent event : store.events) {
                if (event == null || event.severity == null) {
                    continue;
                }

                if (event.severity.ordinal() >= minimumSeverity.ordinal()
                        && event.timestamp >= windowStart
                        && event.timestamp <= currentTime) {
                    matching.add(event);
                }
            }
        }

        boolean alert = threshold > 0 && matching.size() >= threshold;
        return new MonitorResult(alert, matching.size(), Collections.unmodifiableList(new ArrayList<SecurityEvent>(matching)), minimumSeverity, threshold);
    }

    public static String generateReport(SecurityEventStore store, MonitorResult result) {
        StringBuilder report = new StringBuilder();
        report.append("SECURITY EVENT MONITORING REPORT\n");
        report.append("================================\n");

        int totalEvents = store == null ? 0 : store.events.size();
        report.append("Total events stored: ").append(totalEvents).append('\n');

        if (result != null) {
            report.append("Minimum monitored severity: ").append(result.minimumSeverity).append('\n');
            report.append("Alert threshold: ").append(result.threshold).append('\n');
            report.append("Matching events: ").append(result.count).append('\n');
            report.append("Alert state: ").append(result.alert ? "TRIGGERED" : "NONE").append('\n');

            if (result.alert) {
                report.append("ALERT: Threshold exceeded for events at or above ")
                      .append(result.minimumSeverity)
                      .append('\n');

                for (SecurityEvent event : result.matchingEvents) {
                    report.append(" - ").append(formatEvent(event)).append('\n');
                }
            }
        }

        return report.toString();
    }

    public static String formatEvent(SecurityEvent event) {
        if (event == null) {
            return "NULL_EVENT";
        }

        return String.format(
            Locale.ROOT,
            "[%s] [%s] user=%s sourceIp=%s message=%s timestamp=%d",
            event.type,
            event.severity,
            event.user,
            event.sourceIp,
            event.message,
            event.timestamp
        );
    }

    public static int parseInteger(String[] args, int index, int defaultValue) {
        if (args == null || index < 0 || index >= args.length) {
            return defaultValue;
        }

        try {
            return Integer.parseInt(args[index]);
        } catch (NumberFormatException ex) {
            return defaultValue;
        }
    }

    public static long parseLong(String[] args, int index, long defaultValue) {
        if (args == null || index < 0 || index >= args.length) {
            return defaultValue;
        }

        try {
            return Long.parseLong(args[index]);
        } catch (NumberFormatException ex) {
            return defaultValue;
        }
    }

    public static Severity parseSeverity(String[] args, int index, Severity defaultValue) {
        if (args == null || index < 0 || index >= args.length || args[index] == null) {
            return defaultValue;
        }

        try {
            return Severity.valueOf(args[index].toUpperCase(Locale.ROOT));
        } catch (IllegalArgumentException ex) {
            return defaultValue;
        }
    }

